class SchemaInconsistent(Exception):
    pass


def raise_value_error(param, value):
    msg = "Incorrect value of {param} parameter: {value}. " \
          "Please check the method documentation or go to FDSW RC for more details.".format(param=param,
                                                                                            value=value,
                                                                                            )
    raise ValueError(msg)
